import json, sys, re
from collections import Counter, defaultdict
from datetime import datetime

data = json.load(sys.stdin)
events = data.get('data', [])

# Filter to last 6 months (Oct 2025 - Apr 2026)
cutoff = '2025-10-01'
recent = [e for e in events if e.get('created_at','') >= cutoff]
print(f'Events in last 6 months: {len(recent)}')

# Categorize by task patterns
categories = defaultdict(list)
for e in recent:
    target = e.get('target','')
    bucket = e.get('bucket',{}).get('name','')

    if re.search(r'wireframe', target, re.I):
        categories['Wireframes'].append(target)
    elif re.search(r'mockup.*home.*round [12]|home.*round [12]', target, re.I):
        categories['Homepage Mockups'].append(target)
    elif re.search(r'mockup.*round [23]|round [23].*mockup', target, re.I):
        categories['Mockup Revisions (R2/R3)'].append(target)
    elif re.search(r'internal (page|template)|page.*template|template.*page', target, re.I):
        categories['Internal Pages / Templates'].append(target)
    elif re.search(r'(LP|landing page|TY page|thank you)', target, re.I):
        categories['Landing Pages & TY Pages'].append(target)
    elif re.search(r'redesign', target, re.I):
        categories['Redesigns'].append(target)
    elif re.search(r'anchor page|service page', target, re.I):
        categories['Anchor / Service Pages'].append(target)
    elif re.search(r'blog|case stud', target, re.I):
        categories['Blog / Case Study Pages'].append(target)
    elif re.search(r'script|callrail|tracking|CallRail', target, re.I):
        categories['Tracking Scripts & CallRail'].append(target)
    elif re.search(r'edit|update|resize|copy|button|hours|cta', target, re.I):
        categories['Website Edits & Updates'].append(target)
    elif re.search(r'countdown|timer', target, re.I):
        categories['Countdown Timers'].append(target)
    elif target:
        categories['Other'].append(target)

# Unique client buckets
buckets = set(e.get('bucket',{}).get('name','') for e in recent if e.get('bucket',{}).get('name',''))
print(f'\nUnique client projects: {len(buckets)}')

print('\n--- Task Categories (unique task count) ---')
for cat, items in sorted(categories.items(), key=lambda x: -len(x[1])):
    unique = list(set(items))
    print(f'\n{cat}: {len(unique)} unique tasks')
    for i in unique[:5]:
        print(f'  - {i}')
    if len(unique) > 5:
        print(f'  ... and {len(unique)-5} more')
